func ttBrief(t *strings.Builder, nodes *port.Cells, attrs *port.Cells, text *port.Cells) int32 {
	// The brief of the Model (see the head of this file): every node but the root, in id order.
	var n int32 = model.NodeCount(nodes)
	var i int32 = 1
	var kind int32 = 0
	var a int32 = 0
	var v int32 = 0
	for i < n {
		kind = model.NodeKind(nodes, i)
		if kind == model.NkParagraph() {
			port.TextCp(t, 80)
			port.TextCp(t, 91)
			ttRunText(nodes, i, text, t)
			port.TextCp(t, 93)
			port.TextCp(t, 59)
		}
		if kind == model.NkNote() {
			port.TextCp(t, 78)
			port.TextCp(t, 59)
		}
		if kind == model.NkTable() {
			port.TextCp(t, 84)
			port.TextI32(t, model.NodeAttrIntOr(nodes, attrs, i, model.FkColumns(), 0))
			a = model.NodeAttr(nodes, attrs, i, model.FkProfile())
			if a >= 0 {
				port.TextCp(t, model.TextAt(text, model.AttrValue(attrs, a)))
			}
			port.TextCp(t, 59)
		}
		if kind == model.NkCaption() {
			port.TextCp(t, 75)
			port.TextCp(t, 91)
			a = model.NodeAttr(nodes, attrs, i, model.FkLabel())
			if a >= 0 {
				v = 0
				for v < model.AttrLen(attrs, a) {
					port.TextCp(t, model.TextAt(text, model.AttrValue(attrs, a)+v))
					v += 1
				}
			}
			port.TextCp(t, 124)
			ttRunText(nodes, i, text, t)
			port.TextCp(t, 93)
			port.TextCp(t, 59)
		}
		if kind == model.NkRowgroup() {
			port.TextCp(t, 71)
			if model.NodeSub(nodes, i) == 1 {
				port.TextCp(t, 104)
			}
			if model.NodeSub(nodes, i) == 2 {
				port.TextCp(t, 98)
			}
			if model.NodeSub(nodes, i) == 3 {
				port.TextCp(t, 102)
			}
			port.TextCp(t, 59)
		}
		if kind == model.NkRow() {
			port.TextCp(t, 82)
			port.TextCp(t, 59)
		}
		if kind == model.NkCell() {
			port.TextCp(t, 67)
			v = model.NodeAttrIntOr(nodes, attrs, i, model.FkRowspan(), 1)
			if v > 1 {
				port.TextCp(t, 114)
				port.TextI32(t, v)
			}
			v = model.NodeAttrIntOr(nodes, attrs, i, model.FkColspan(), 1)
			if v > 1 {
				port.TextCp(t, 99)
				port.TextI32(t, v)
			}
			if model.NodeSub(nodes, i) == 1 {
				port.TextCp(t, 104)
			}
			if model.NodeSub(nodes, i) == 2 {
				port.TextCp(t, 119)
			}
			v = model.NodeAttrIntOr(nodes, attrs, i, model.FkAlign(), 0)
			if v == 1 {
				port.TextCp(t, 115)
			}
			if v == 2 {
				port.TextCp(t, 99)
			}
			if v == 3 {
				port.TextCp(t, 101)
			}
			port.TextCp(t, 91)
			ttRunText(nodes, i, text, t)
			port.TextCp(t, 93)
			port.TextCp(t, 59)
		}
		i += 1
	}
	return 0
}

